@testset "localtonemap 补充" begin
    HDR = Float32[(row + 2col)^2 / 40 for row in 1:12, col in 1:15]
    RGB = cat(HDR, HDR .* 0.6f0, HDR .* 0.2f0; dims=3)

    @testset "RangeCompression 缺失数据类型" begin
        scalar_values = (
            0.5f0, Int8(1), Int16(1), Int32(1), Int64(1),
            UInt8(1), UInt16(1), UInt32(1), UInt64(1),
        )
        for value in scalar_values
            output = localtonemap(HDR; RangeCompression=value)
            @test typeof(output) == typeof(HDR)
            @test all(v -> 0 <= v <= 1, output)
        end
    end

    @testset "EnhanceContrast 缺失数据类型" begin
        scalar_values = (
            0.5f0, Int8(0), Int16(0), Int32(0), Int64(0),
            UInt8(0), UInt16(0), UInt32(0), UInt64(0),
        )
        for value in scalar_values
            output = localtonemap(RGB; EnhanceContrast=value)
            @test typeof(output) == typeof(RGB)
            @test all(v -> 0 <= v <= 1, output)
        end
    end
